import {studyBlocks} from './study-plan-content.mjs';
import {videoTiming} from './video-timing.mjs';
import {instrumentLessons} from './instrument-content.mjs';
import {units,levels,videos} from './learning-content.mjs';
import {circuits,circuitSvg} from './circuit-library.mjs';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function mountLearningStudio(api){
 const $=id=>document.getElementById(id);let progress={},active=null,step=0,filter='all',search='',phase=0;
 try{progress=JSON.parse(api.storage.getItem('circuitlab-studio-v7')||'{}');if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};}catch{}
 const location=document.createElement('section');location.id='learningLocation';document.querySelector('header').after(location);
 const recommended=()=>units.find(u=>!progress[u.id]?.passed)||units[0];
 function locate(u,where){location.innerHTML=`<div><small>ESTÁS AQUÍ · ${esc(where)}</small><b>${u?`Bloque ${studyBlocks.findIndex(b=>b.lessons.includes('u:'+u.id))+1} de 10 · Lección ${studyBlocks.flatMap(b=>b.lessons).indexOf('u:'+u.id)+1} de ${studyBlocks.flatMap(b=>b.lessons).length} · ${u.title}`:'Inicio del curso · tu ruta de aprendizaje'}</b></div><button id="backToRoute">⌂ Mi ruta</button>`;$('backToRoute').onclick=()=>{article.close();api.show('course');(document.getElementById('studyPlan')||host).scrollIntoView({behavior:'smooth'});};}
 document.addEventListener('circuitlab:page',e=>{const labels={course:'Mi ruta',library:'Biblioteca · consulta opcional',lab:active?'Práctica guiada · paso '+(step+1)+' de 6':'Banco libre · elige Mi ruta para empezar',scope:'Laboratorio de señales'};locate(e.detail==='lab'?active:null,labels[e.detail]);});
 const save=()=>{try{api.storage.setItem('circuitlab-studio-v7',JSON.stringify(progress));}catch{}};
 const host=document.createElement('section');host.id='learningStudio';$('coursePage').prepend(host);
 const guide=document.createElement('section');guide.id='guidedPractice';guide.className='guidedPractice';guide.hidden=true;document.querySelector('#labPage .center').prepend(guide);
 const article=document.createElement('dialog');article.id='studyDialog';document.body.append(article);
 function render(){const next=recommended(),done=units.filter(u=>progress[u.id]?.passed).length;host.innerHTML=`<div class="routeWelcome"><span class="studioKicker">TU CURSO DE ELECTRÓNICA · PASO A PASO</span><h1>${done?'Sigue desde aquí.':'Empieza aquí.'}</h1><p>Una lección cada vez. Primero entiendes, después observas y por último lo haces sobre la placa.</p></div><section class="nextLesson"><div><span class="routeBadge">${done===12?'REPASO RECOMENDADO':'TU SIGUIENTE PASO'} · NIVEL ${next.level+1}</span><h2>${units.indexOf(next)+1}. ${next.title}</h2><p>${next.goal}</p><small>${next.minutes} minutos orientativos · Puedes parar y volver</small></div><button id="studioResume" class="academyPrimary">${done?'Continuar mi curso':'Empezar desde cero'} →</button></section><div class="routeProgress"><span><b>${done} de 12</b> lecciones completadas</span><progress max="12" value="${done}" aria-label="Lecciones completadas"></progress><small>Se guarda en este navegador</small></div><div class="learningLegend"><span class="theoryLabel">01 · TEORÍA<br><small>Entiende la idea</small></span><span class="demoLabel">02 · DEMOSTRACIÓN<br><small>Mira el ejemplo y el vídeo</small></span><span class="practiceLabel">03 · PRÁCTICA 3D<br><small>Hazlo y comprueba</small></span></div><section class="routeMap"><h2>Tu camino, de principio a fin</h2><p>«Ahora» indica la lección recomendada. Puedes abrir otras para repasar.</p>${levels.map((l,n)=>`<div class="routeStage"><h3>${l}</h3><div>${units.filter(u=>u.level===n).map(u=>`<button data-route="${u.id}" class="${progress[u.id]?.passed?'routeDone':u.id===next.id?'routeNow':'routeLater'}" ${u.id===next.id?'aria-current="step"':''}><span>${progress[u.id]?.passed?'✓ Completada':u.id===next.id?'→ Ahora':'○ Después'} · LECCIÓN ${units.indexOf(u)+1}</span><b>${u.title}</b></button>`).join('')}</div></div>`).join('')}</section><details class="optionalResources"><summary>Apoyo del banco · 12 unidades de teoría y práctica 3D</summary><div class="studioHeading"><h2>Buscar una lección</h2><label>Buscar<input id="studioSearch" type="search" placeholder="Pistas, diagnóstico…" value="${esc(search)}"></label></div><div class="levelFilters"><button data-level="all">Todos</button>${levels.map((l,i)=>`<button data-level="${i}">${l}</button>`).join('')}</div><div id="unitCards" class="unitCards"></div></details><details class="optionalResources"><summary>Instrumentos · 9 prácticas de osciloscopio y generador</summary><section class="instrumentCourse"><p>Complemento de las lecciones. Cada guía indica qué control mover y comprueba tu configuración.</p><div class="instrumentCourseGrid">${instrumentLessons.map((l,i)=>`<button data-instrument="scope" data-lesson="${l.id}"><span>${i+1} · ${l.steps.length} pasos</span><b>${l.title}</b><small>Abrir guía →</small></button>`).join('')}</div></section></details><details class="optionalResources"><summary>Videoteca · ${videos.length} demostraciones con voz en castellano</summary><section class="videoLibrary"><div class="videoCards">${videos.map((v,i)=>`<button data-video="${i}"><img src="videos/${v.id}.jpg" alt="${esc(v.title)}" loading="lazy"><span>▶ ${Math.ceil(videoTiming[v.id].duration)} s · Con voz</span><h3>${v.title}</h3><p>${v.description}</p></button>`).join('')}</div></section></details>`;
 host.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>openUnit(units.find(u=>u.id===b.dataset.route)));
 cards();$('studioResume').onclick=()=>openUnit(recommended());$('studioSearch').oninput=e=>{search=e.target.value;cards();};host.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{filter=b.dataset.level;render();});host.querySelectorAll('[data-video]').forEach(b=>b.onclick=()=>openVideo(Number(b.dataset.video)));
 }
 function cards(){const list=units.filter(u=>(filter==='all'||u.level===Number(filter))&&`${u.title} ${u.goal}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));$('unitCards').innerHTML=list.map(u=>`<button class="unitCard" data-unit="${u.id}"><div><span>${levels[u.level]}</span><b>${progress[u.id]?.passed?'✓':'↗'}</b></div><h3>${u.title}</h3><p>${u.goal}</p><footer>${u.minutes} min orientativos <span>${progress[u.id]?.passed?'Comprobada':'Teoría + práctica 3D'}</span></footer></button>`).join('')||'<p>No hay unidades con estos filtros.</p>';$('unitCards').querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>openUnit(units.find(u=>u.id===b.dataset.unit)));}
 function dialog(html){article.innerHTML=`<button class="studyClose" id="studyClose" aria-label="Cerrar">×</button>${html}`;if(!article.open)article.showModal();article.scrollTop=0;$('studyClose').onclick=()=>{article.querySelector('video')?.pause();article.close();};}
 article.addEventListener('close',()=>{article.querySelector('video')?.pause();if(!$('coursePage').hidden)locate(null,'Mi ruta');else if(!$('labPage').hidden)locate(guide.hidden?null:active,guide.hidden?'Banco libre':'03 · Práctica 3D · paso '+(step+1)+' de 6');else locate(null,'Consulta de recursos');});
 function openUnit(u,page=0){phase=page;const c=circuits.find(c=>c.id===u.pattern);locate(u,['01 · Teoría','02 · Demostración','03 · Preparación de práctica'][phase]);
 const panels=[`<div class="studyPrereq"><b>Antes de empezar</b><p>${u.prerequisite}</p></div><div class="theoryLayout"><div>${u.theory.map(([h,t],i)=>`<section class="theoryBlock"><span>IDEA ${i+1}</span><h3>${h}</h3><p>${t}</p></section>`).join('')}</div><figure>${c?circuitSvg(c.kind):''}<figcaption>Esquema de principio · ${c?.name||''}</figcaption></figure></div>`,`<section class="workedExample"><b>Ejemplo resuelto</b><p>${u.example}</p></section><p class="studyTrap"><b>Fíjate en esto</b> · ${u.trap}</p><button id="unitVideo">▶ Ver demostración con voz</button><p>Pausa el vídeo para relacionar cada terminal con su pista. Después vuelve aquí para comprobar lo aprendido.</p>`,`<section class="studyQuiz"><span class="eyebrow">ANTES DE TOCAR LA PLACA</span><h3>${u.question}</h3>${u.answers.map((a,i)=>`<button data-quiz="${i}">${a}</button>`).join('')}<p id="studyQuizFeedback" role="status">${progress[u.id]?.quiz?'✓ Comprensión comprobada. Ya puedes practicar.':'Elige una respuesta. Te explicaremos el porqué.'}</p></section><div class="practicePreview"><b>Qué vas a hacer en la placa</b><p>1. Preparar el banco → 2. Localizar ${u.net} → 3. Seguir y marcar → 4. Predecir → 5. Comprobar → 6. Explicar.</p><p>La guía aparecerá encima de la placa. No necesitas elegir otro reto ni otra placa.</p></div>`];
 dialog(`<p class="eyebrow">BLOQUE ${studyBlocks.findIndex(b=>b.lessons.includes('u:'+u.id))+1} DE 10 · LECCIÓN ${studyBlocks.flatMap(b=>b.lessons).indexOf('u:'+u.id)+1} DE ${studyBlocks.flatMap(b=>b.lessons).length}</p><h2>${u.title}</h2><p class="studyLead">${u.goal}</p><nav class="phaseTabs" aria-label="Etapas de la lección">${['01 · Teoría','02 · Demostración','03 · Práctica 3D'].map((t,i)=>`<button data-phase="${i}" class="phase${i} ${phase===i?'selected':''}" ${phase===i?'aria-current="step"':''}>${t}</button>`).join('')}</nav><div class="phasePanel phase${phase}">${panels[phase]}</div><div class="studyActions"><button id="lessonPrevious">${phase?'← Anterior':'← Mi ruta'}</button><button id="${phase===2?'unitPractice':'lessonNext'}" class="academyPrimary" ${phase===2&&!progress[u.id]?.quiz?'disabled':''}>${phase===0?'Entendido · ver ejemplo →':phase===1?'Comprobar y practicar →':'Empezar práctica guiada →'}</button></div>`);
 document.dispatchEvent(new CustomEvent('circuitlab:lesson-open',{detail:{target:'studyDialog',id:'u:'+u.id}}));
 article.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>openUnit(u,Number(b.dataset.phase)));
 $('lessonPrevious').onclick=()=>{if(phase)openUnit(u,phase-1);else{article.close();api.show('course');}};
 $('lessonNext')?.addEventListener('click',()=>openUnit(u,phase+1));
 article.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.quiz)===u.correct;progress[u.id]={...progress[u.id],quiz:ok};save();$('studyQuizFeedback').textContent=(ok?'✓ Correcto. ':'Vuelve a intentarlo. ')+u.why;$('unitPractice').disabled=!ok;});
 if($('unitPractice'))$('unitPractice').onclick=()=>{if(!progress[u.id]?.quiz)return;article.close();launch(u);};
 if($('unitVideo'))$('unitVideo').onclick=()=>openVideo(u.video,u);
 }
 function openVideo(i,u){const v=videos[i];dialog(`<p class="eyebrow">MICROLECCIÓN 3D · VOZ EN CASTELLANO · RÓTULOS Y TRANSCRIPCIÓN</p><h2>${v.title}</h2><p>${v.description}</p><video id="trainingVideo" controls playsinline preload="metadata" poster="videos/${v.id}.jpg"><source src="videos/${v.id}.mp4?v=13" type="video/mp4"><track default kind="subtitles" srclang="es" label="Español" src="videos/${v.id}.vtt?v=13"></video><div class="audioControl"><button id="playWithVoice" class="academyPrimary">▶ Reproducir con voz</button><span id="audioStatus" role="status">Pulsa para activar imagen y voz.</span></div><div class="videoChapters">${v.chapters.map((x,j)=>`<button data-seek="${videoTiming[v.id].starts[j]}">${Math.floor(videoTiming[v.id].starts[j])}s · ${x}</button>`).join('')}</div><details open><summary>Transcripción de la lección</summary><ol>${v.transcript.map(t=>`<li>${t}</li>`).join('')}</ol></details><div class="studyActions">${u?'<button id="returnLesson">← Volver a mi lección</button>':''}<button id="videoPractice" class="academyPrimary">Practicarlo en una placa →</button></div>`);document.dispatchEvent(new CustomEvent('circuitlab:lesson-open',{detail:{target:'studyDialog',id:u?'u:'+u.id:'video:'+v.id}}));if(u)$('returnLesson').onclick=()=>{article.querySelector('video').pause();openUnit(u,1);};$('playWithVoice').onclick=async()=>{const player=$('trainingVideo');player.muted=false;try{await player.play();$('audioStatus').textContent='Voz activada · ajusta también el volumen de tu dispositivo.';}catch{$('audioStatus').textContent='Pulsa el control ▶ del vídeo para iniciar la reproducción.';}};article.querySelectorAll('[data-seek]').forEach(b=>b.onclick=()=>{$('trainingVideo').currentTime=Number(b.dataset.seek);});$('videoPractice').onclick=()=>{article.querySelector('video').pause();article.close();if(v.instrument)document.dispatchEvent(new CustomEvent('circuitlab:instruments',{detail:{lesson:v.instrument}}));else launch(u||units[[0,3,6][i]]||units[0]);};}
 function launch(u){active=u;step=0;document.getElementById('labPage').classList.add('guidedMode');api.launch(u.mission);guide.hidden=false;renderGuide();guide.scrollIntoView({behavior:'smooth',block:'start'});}
 const titles=['Preparar','Localizar','Seguir','Predecir','Comprobar','Transferir'];
 function renderGuide(){if(!active)return;const u=active;locate(u,'03 · Práctica 3D · paso '+(step+1)+' de 6');const m=api.missions[u.mission],p=progress[u.id]||{};
 const content=[`<p><b>Objetivo:</b> ${u.goal}</p><p><b>Placa:</b> ${m.board}. Primero observa sin activar la fuente.</p><p>${u.prerequisite}</p>`,`<p>Localiza y selecciona la red <b>${u.net}</b> en la placa. Consulta sus terminales en «Lo que estás siguiendo».</p><p>El cobre seleccionado se ilumina. Usa el buscador de redes si la placa es compleja.</p>`,`<p>Con <b>${u.net}</b> seleccionada, pulsa <b>Marcar red seleccionada</b> y después <b>Voltear</b>. La marca debe conservarse en ambas caras.</p><p>Una red puede no tener pistas en una cara concreta. Confirma los pads y las capas disponibles.</p>`,`<p>${u.example}</p><label>Mi predicción: puntos, condición y resultado esperado<textarea id="prediction" placeholder="Espero… entre… con…">${esc(p.prediction||'')}</textarea></label>`,`<p><b>${m.title}</b></p><p>${m.text}</p><details><summary>Necesito una pista</summary><p>${m.hint}</p></details><p>Realiza la acción en la placa y en los instrumentos; después pulsa Comprobar paso.</p>`,`<p>${u.transfer}</p><label>Mi conclusión y qué comprobaría después<textarea id="conclusion" placeholder="He observado… Esto respalda… Falta comprobar…">${esc(p.conclusion||'')}</textarea></label><p>La conclusión se guarda como autoevaluación. La validación automática verifica las condiciones del reto.</p>`][step];
 guide.innerHTML=`<div class="guidedHeading"><div><span class="eyebrow">PRÁCTICA 3D · LECCIÓN ${studyBlocks.flatMap(b=>b.lessons).indexOf('u:'+u.id)+1}/${studyBlocks.flatMap(b=>b.lessons).length} · PASO ${step+1}/6</span><h2>${u.title}</h2></div><button id="closePractice" aria-label="Cerrar guía">×</button></div><div class="guidedSteps">${titles.map((t,i)=>`<span class="${i===step?'current':i<step?'past':''}">${i+1} ${t}</span>`).join('')}</div><div class="guidedBody"><div><h3>${titles[step]}</h3>${content}</div><aside><b>Qué estás aprendiendo</b><p>${u.goal}</p><button id="reviewTheory">Consultar teoría</button><button id="guideVideo">▶ Ver vídeo</button><button id="guideInstruments">Osciloscopio y generador</button></aside></div><div class="guidedButtons"><button id="stepBack" ${step===0?'disabled':''}>← Anterior</button><button id="checkStep" class="academyPrimary">${step===5?'Guardar y finalizar':'Comprobar paso →'}</button></div><p id="stepFeedback" role="status" aria-live="polite"></p>`;
 $('closePractice').onclick=()=>{guide.hidden=true;document.getElementById('labPage').classList.remove('guidedMode');locate(null,'Banco libre');};$('reviewTheory').onclick=()=>openUnit(u,2);$('guideVideo').onclick=()=>openVideo(u.video,u);$('guideInstruments').onclick=()=>document.dispatchEvent(new CustomEvent('circuitlab:instruments',{detail:{unit:units.indexOf(u)}}));$('stepBack').onclick=()=>{stash();step--;renderGuide();};$('prediction')?.addEventListener('input',stash);$('conclusion')?.addEventListener('input',stash);
 $('checkStep').onclick=()=>{stash();const s=api.snapshot();let msg='';if(s.board!==m.board||s.mission!==u.mission)msg='Has cambiado de placa o reto. Abre de nuevo esta unidad para recuperar su práctica.';else if(step===1&&s.net!==u.net)msg='Selecciona '+u.net+' en la lista de redes o en sus pads.';else if(step===2&&(!s.bottom||s.net!==u.net||!s.marked))msg='Marca '+u.net+' y voltea la placa; comprueba que sigue seleccionada.';else if(step===3&&(progress[u.id]?.prediction||'').trim().length<20)msg='Escribe una predicción que incluya puntos y condiciones (al menos 20 caracteres).';else if(step===4&&!api.verify())msg='Todavía no se cumplen las condiciones del reto. Revisa el estado, las puntas y el modo; abre la pista para orientarte.';else if(step===5&&(!progress[u.id]?.quiz||(progress[u.id]?.conclusion||'').trim().length<20))msg='Completa la pregunta de teoría y escribe una conclusión (al menos 20 caracteres).';if(msg){$('stepFeedback').textContent=msg;return;}if(step<5){step++;renderGuide();}else{progress[u.id]={...progress[u.id],passed:true};save();render();document.dispatchEvent(new CustomEvent('circuitlab:progress'));$('stepFeedback').textContent='✓ Unidad comprobada. Tu predicción y conclusión están guardadas en este dispositivo.';$('checkStep').textContent='✓ Ver mi progreso y siguiente lección →';$('checkStep').onclick=()=>{guide.hidden=true;api.show('course');(document.getElementById('studyPlan')||host).scrollIntoView({behavior:'smooth'});};}};
 }
 function stash(){if(!active)return;progress[active.id]={...progress[active.id],...($('prediction')?{prediction:$('prediction').value}:{}),...($('conclusion')?{conclusion:$('conclusion').value}:{})};save();}
 render();api.show('course');locate(null,'Mi ruta');
 return {openUnit:id=>openUnit(units.find(u=>u.id===id))};
}
